import "./orderlist.css";
import { useCart } from "./CartContext";
import { useNavigate } from "react-router-dom";

const OrderList = () => {
    const { orders, setOrders } = useCart();
    const navigate = useNavigate();

    // Handle placing order
    const handlePlaceOrder = () => {
        alert("Đặt hàng thành công!");
        setOrders([]); // Clear orders after placing
        navigate("/cart");
    };

    if (!orders || orders.length === 0) {
        return <p>Chưa có đơn hàng nào.</p>;
    }

    return (
        <div className="container mt-5">

            {orders.map((order) => (
                <div key={order.id} className="order-item mb-4 p-4 border rounded shadow-sm">

                    <h2 className="mb-4">Thông tin giao hàng</h2>
                    <div className="row mb-3">
                        <div className="col-md-4">
                            <strong>Thông tin</strong>
                            <p>{order.info}</p>
                        </div>
                        <div className="col-md-4">
                            <strong>Họ & Tên</strong>
                            <p>{order.name}</p>
                        </div>
                        <div className="col-md-4">
                            <strong>Địa chỉ</strong>
                            <p>{order.address}</p>
                        </div>
                    </div>
                    <div className="row mb-3">
                        <div className="col-md-4">
                            <strong>Tỉnh</strong>
                            <p>{order.city}</p>
                        </div>
                        <div className="col-md-8">
                            <strong>Ghi chú</strong>
                            <input className="form-control" type="text" placeholder="Ghi chú" />
                        </div>
                    </div>

                    <div className="row mb-3">
                        <div className="col-md-6">
                            <strong>Ngày đặt</strong>
                            <p>{order.date}</p>
                        </div>
                    </div>

                    <h3 className="mt-4">Đơn hàng ({order.items.reduce((total, item) => total + (item.quantity || 1), 0)} sản phẩm)</h3>

                    <div className="order-items">
                        {order.items.map((item, index) => (
                            <div key={index} className="d-flex align-items-center mb-2">
                                <img src={item.image} alt={item.name} className="order-item-image" style={{ width: "50px", height: "50px", objectFit: "cover" }} />
                                <span className="ms-3">{item.name} - {item.price}k</span>
                            </div>
                        ))}
                    </div>

                    <h4 className="mt-3">Tổng giá trị: {order.items.reduce((sum, item) => sum + item.price * (item.quantity || 1), 0)}k</h4>
                    <button className="btn btn-success w-100 mt-3" onClick={handlePlaceOrder}>Đặt hàng</button>
                </div>
            ))}

        </div>
    );
};

export default OrderList;
